function nowIso(){return new Date().toISOString();}
function nowHms(){const d=new Date(),pad2=n=>String(n).padStart(2,'0');return `${pad2(d.getHours())}:${pad2(d.getMinutes())}:${pad2(d.getSeconds())}`;}
function friendlyErrorMessage(err){const code=String(err||'');if(!code)return'';const map={timeout:'请求超时',read_blob_failed:'读取图片数据失败',question_element_not_found:'未找到题目元素',img_src_empty:'图片地址为空',svg_image_href_empty:'矢量图（SVG）图片链接为空',canvas_tainted_or_failed:'画布（Canvas）跨域污染或转换失败',background_url_empty:'背景图地址为空',unsupported_question_element:'不支持的题目元素类型',json_not_found:'未在模型返回中找到 JSON',json_parse_failed:'模型返回的 JSON 解析失败',score_invalid:'模型返回的分数无效',confidence_invalid:'模型返回的置信度无效',api_key_empty:'未填写 API 密钥',upstream_json_parse_failed:'上游响应不是合法 JSON',unknown_provider:'未知服务商类型',rate_limited:'请求过于频繁',invalid_image_url:'图片URL无效或模型不支持'};const label=map[code];return label?`${label}（${code}）`:code;}
function friendlyStageLabel(stage){const code=String(stage||'');if(!code)return'';const map={parse_upstream_json:'解析上游响应 JSON',parse_model_json:'解析模型返回 JSON'};const label=map[code];return label?`${label}（${code}）`:code;}
function toHms(timeLike){const s=String(timeLike||'');if(/^\d{2}:\d{2}:\d{2}$/.test(s))return s;const d=new Date(s);if(Number.isFinite(d.getTime())){const pad2=n=>String(n).padStart(2,'0');return `${pad2(d.getHours())}:${pad2(d.getMinutes())}:${pad2(d.getSeconds())}`;}return s.slice(0,8);}
function log(level,message,data){const nextData=(()=>{if(!data||typeof data!=='object')return data;if(typeof data.error!=='string')return data;return{...data,error:friendlyErrorMessage(data.error)}})();const entry={time:nowHms(),timeIso:nowIso(),level,message,data:nextData};const consoleFn=level==='error'?console.error:level==='warn'?console.warn:console.log;try{consoleFn('[AI 阅卷助手]',`[${entry.timeIso}]`,level.toUpperCase(),message,nextData||'');}catch{}state.logs.push(entry);if(state.logs.length>300)state.logs.shift();renderLogs();if(level==='error'&&statusEl){const errMsg=typeof message==='string'?message:(message?.message||String(message));setText(statusEl,`错误: ${errMsg.slice(0,80)}`);setTimeout(()=>{if(statusEl&&!state.running)setText(statusEl,'未运行');else if(statusEl&&state.running)setText(statusEl,'运行中…');},5000);}}
function deepMerge(base,patch){if(patch===null||patch===undefined)return base;if(Array.isArray(base)||Array.isArray(patch))return structuredClone(patch);if(!isPlainObject(base)||!isPlainObject(patch))return structuredClone(patch);const out={...base};for(const[k,v]of Object.entries(patch)){out[k]=k in base?deepMerge(base[k],v):structuredClone(v);}return out;}
function isPlainObject(v){return Boolean(v)&&typeof v==='object'&&!Array.isArray(v);}
function normalizeSiteConfig(siteCfg){if(!isPlainObject(siteCfg))return structuredClone(DEFAULT_SITE_CONFIG);const out=deepMerge(structuredClone(DEFAULT_SITE_CONFIG),siteCfg);if(!isPlainObject(out.image))out.image=structuredClone(DEFAULT_SITE_CONFIG.image);if(typeof out.image.selector!=='string')out.image.selector='';if(typeof out.image.kind!=='string')out.image.kind='auto';if(!isPlainObject(out.score))out.score=structuredClone(DEFAULT_SITE_CONFIG.score);if(typeof out.score.containerSelector!=='string')out.score.containerSelector='';if(!isPlainObject(out.score.mapping))out.score.mapping={};if(!isPlainObject(out.nav))out.nav={};return out;}
function normalizeConfig(cfg){if(!isPlainObject(cfg))return structuredClone(DEFAULT_CONFIG);const out=deepMerge(structuredClone(DEFAULT_CONFIG),cfg);if(!isPlainObject(out.global))out.global=structuredClone(DEFAULT_CONFIG.global);if(!isPlainObject(out.global.provider))out.global.provider=structuredClone(DEFAULT_CONFIG.global.provider);if(!isPlainObject(out.global.prompt))out.global.prompt=structuredClone(DEFAULT_CONFIG.global.prompt);if(typeof out.global.prompt.system!=='string'||!out.global.prompt.system.trim())out.global.prompt.system=DEFAULT_CONFIG.global.prompt.system;if(typeof out.global.prompt.user!=='string')out.global.prompt.user=DEFAULT_CONFIG.global.prompt.user;if(typeof out.global.imageSendMode!=='string')out.global.imageSendMode=DEFAULT_CONFIG.global.imageSendMode;if(typeof out.global.continueOnJsonError!=='boolean')out.global.continueOnJsonError=DEFAULT_CONFIG.global.continueOnJsonError;if(typeof out.global.theme!=='string')out.global.theme=DEFAULT_CONFIG.global.theme;if(!isPlainObject(out.sites))out.sites={};for(const[k,v]of Object.entries(out.sites)){out.sites[k]=normalizeSiteConfig(v);}return out;}
function extractImportedSiteConfig(obj,key){if(!isPlainObject(obj))return null;if(isPlainObject(obj.sites)&&isPlainObject(obj.sites[key]))return obj.sites[key];if(isPlainObject(obj[key]))return obj[key];if('image'in obj||'score'in obj||'adapter'in obj||'nav'in obj)return obj;return null;}
async function loadConfig(){const raw=await GM_getValue(STORAGE_KEY,null);if(!raw)return structuredClone(DEFAULT_CONFIG);try{const parsed=typeof raw==='string'?JSON.parse(raw):raw;return normalizeConfig(parsed);}catch{return structuredClone(DEFAULT_CONFIG);}}
async function saveConfig(){await GM_setValue(STORAGE_KEY,JSON.stringify(state.config));}
