function getSiteAdapter(){return SITE_ADAPTERS[siteKey()]||DEFAULT_SITE_ADAPTER;}
function resolveImageElement(el){if(!el)return el;const adapter=getSiteAdapter();if(adapter&&typeof adapter.imageResolver==='function'){try{const resolved=adapter.imageResolver(el);if(resolved)return resolved;}catch(e){log('warn','调用站点图片解析器失败',{error:String(e)});}}return el;}
function ensureSiteConfig(){const key=siteKey();if(!isPlainObject(state.config))state.config=structuredClone(DEFAULT_CONFIG);if(!isPlainObject(state.config.sites))state.config.sites={};if(!isPlainObject(state.config.sites[key])){state.config.sites[key]=structuredClone(DEFAULT_SITE_CONFIG);const adapter=getSiteAdapter();if(adapter?.image?.selector){state.config.sites[key].image.selector=adapter.image.selector;state.config.sites[key].image.kind=adapter.image.kind||'auto';}}state.config.sites[key]=normalizeSiteConfig(state.config.sites[key]);return state.config.sites[key];}
function escapeCssIdent(ident){if(window.CSS&&CSS.escape)return CSS.escape(ident);return ident.replace(/[^a-zA-Z0-9_-]/g,'\\$&');}
function isUniqueId(id){if(!id)return false;try{return document.querySelectorAll(`#${escapeCssIdent(id)}`).length===1;}catch{return false;}}
function buildSelector(el){if(!el||el.nodeType!==1)return'';const id=el.getAttribute('id');if(id&&isUniqueId(id))return`#${escapeCssIdent(id)}`;const parts=[];let cur=el;while(cur&&cur.nodeType===1&&cur!==document.documentElement){const tag=cur.tagName.toLowerCase();let part=tag;const className=(cur.getAttribute('class')||'').split(/\s+/).filter(Boolean).slice(0,3);if(className.length)part+='.'+className.map(escapeCssIdent).join('.');const parent=cur.parentElement;if(parent){const siblings=Array.from(parent.children).filter(c=>c.tagName===cur.tagName);if(siblings.length>1){const idx=siblings.indexOf(cur)+1;part+=`:nth-of-type(${idx})`;}}parts.unshift(part);const selector=parts.join(' > ');try{const found=document.querySelectorAll(selector);if(found.length===1&&found[0]===el)return selector;}catch{}cur=cur.parentElement;if(parts.length>6)break;}return parts.join(' > ');}
function elementFromSelector(selector){if(!selector)return null;try{return document.querySelector(selector);}catch{return null;}}
function createEl(tag,props,children){const el=document.createElement(tag);if(props){for(const[k,v]of Object.entries(props)){if(k==='class')el.className=v;else if(k==='style'){if(typeof v==='string')el.style.cssText=v;else if(v&&typeof v==='object')Object.assign(el.style,v);}else if(k==='value')el.value=v;else if(k==='checked')el.checked=Boolean(v);else if(k.startsWith('on')&&typeof v==='function')el.addEventListener(k.slice(2),v);else if(v!==false&&v!==null&&v!==undefined)el.setAttribute(k,v);}}if(children){for(const child of children){if(child===null||child===undefined)continue;if(typeof child==='string')el.appendChild(document.createTextNode(child));else if(child instanceof Node)el.appendChild(child);else console.warn('Invalid child in createEl',child);}}return el;}
function setText(el,text){while(el.firstChild)el.removeChild(el.firstChild);el.appendChild(document.createTextNode(text));}
function formatJson(obj){try{return JSON.stringify(obj,null,2);}catch{return String(obj);}}
function debounce(fn,ms){let t=null;return(...args)=>{if(t)clearTimeout(t);t=setTimeout(()=>{t=null;fn(...args);},ms);};}
function formatScalar(v){if(v===null)return'null';if(v===undefined)return'';if(typeof v==='string')return v;if(typeof v==='number'||typeof v==='boolean')return String(v);if(v instanceof Date)return v.toISOString();return String(v);}
