function applyTheme(themeKey){
    const theme=THEMES[themeKey]||THEMES.dark;
    state.config.global.theme=themeKey;
    saveConfig().catch(()=>{});
    const root=document.documentElement;
    root.style.setProperty('--aig-bg',theme.bg);
    root.style.setProperty('--aig-bg2',theme.bg2);
    root.style.setProperty('--aig-bg3',theme.bg3);
    root.style.setProperty('--aig-text',theme.text);
    root.style.setProperty('--aig-text2',theme.text2);
    root.style.setProperty('--aig-border',theme.border);
    root.style.setProperty('--aig-accent',theme.accent);
    root.style.setProperty('--aig-accent-hover',theme.accentHover);
    if(panelEl){
        panelEl.style.background='';
        panelEl.style.color='';
        panelEl.style.borderColor='';
    }
    if(fabEl){
        fabEl.style.background='';
    }
}
