async function recognizeImageFromFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=async(e)=>{const dataUrl=e.target.result;try{const result=await callModelForRecognition(dataUrl);resolve(result);}catch(err){reject(err);}};reader.onerror=()=>reject(new Error('读取图片文件失败'));reader.readAsDataURL(file);});}
async function callModelForRecognition(imageDataUrl){const g=state.config.global;const p=g.provider;if(!p.apiKey&&p.type!=='mock'&&p.type!=='custom')throw new Error('api_key_empty');const recognitionSystem='你是一个图片内容识别助手。请识别图片中的文字、公式、图表等内容，并将其转换为清晰的 LaTeX 或 Markdown 格式输出。只输出识别结果，不要添加额外解释。对于数学公式，请使用 $$...$$ 或 $...$ 包围。对于普通文本，直接输出。对于列表、表格等，请使用 Markdown 语法。';const recognitionUser='请识别这张图片的内容，以 LaTeX/Markdown 格式输出。';if(p.type==='mock'){return'识别模拟内容：\n\n这是一个示例答案。\n\n数学公式：$E=mc^2$';}if(p.type==='openai'){const body={model:p.model,messages:[{role:'system',content:recognitionSystem},{role:'user',content:[{type:'text',text:recognitionUser},{type:'image_url',image_url:{url:imageDataUrl}}]}],max_tokens:4000,temperature:0.2};const resp=await gmRequest({method:'POST',url:p.endpoint,headers:{'Content-Type':'application/json',Authorization:`Bearer ${p.apiKey}`},data:JSON.stringify(body),timeoutMs:g.requestTimeoutMs});const rawText=resp.responseText||'';let respObj;try{respObj=JSON.parse(rawText);}catch{throw new Error('upstream_json_parse_failed');}if(respObj.error)throw new Error(`API 错误：${respObj.error.message||JSON.stringify(respObj.error)}`);const content=respObj.choices?.[0]?.message?.content;if(!content)throw new Error('模型未返回内容');return content.trim();}if(p.type==='custom'){const headers=(()=>{try{return JSON.parse(p.custom?.headersJson||'{}');}catch{return{};}})();const bodyTpl=p.custom?.bodyTemplate||'';const imageDataUrlStr=imageDataUrl;const body=applyTemplate(bodyTpl,{SYSTEM:recognitionSystem,USER:recognitionUser,IMAGE_DATA_URL:imageDataUrlStr,IMAGE_URL:imageDataUrlStr});const resp=await gmRequest({method:'POST',url:p.endpoint,headers,data:body,timeoutMs:g.requestTimeoutMs});const rawText=resp.responseText||'';let respObj=null;try{respObj=JSON.parse(rawText);}catch{}const modelText=extractModelText(respObj,rawText);if(!modelText)throw new Error('模型未返回内容');return modelText.trim();}throw new Error('unknown_provider');}
function buildPromptSection(){const sec=createEl('div',{class:'aig-x7k2-section'});state.config=normalizeConfig(state.config);if(!String(state.config.global.prompt.system||'').trim()){state.config.global.prompt.system=DEFAULT_CONFIG.global.prompt.system;saveConfig();}const sys=createEl('textarea',{value:state.config.global.prompt.system||'',style:{minHeight:'160px'}});const usr=createEl('textarea',{value:state.config.global.prompt.user||'',style:{minHeight:'120px'}});let saveTimer=null;const scheduleSave=()=>{if(saveTimer)clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveTimer=null;saveConfig();},350);};sys.addEventListener('input',()=>{state.config.global.prompt.system=sys.value;scheduleSave();});usr.addEventListener('input',()=>{state.config.global.prompt.user=usr.value;scheduleSave();});const onRecognizeClick=async()=>{const input=document.createElement('input');input.type='file';input.accept='image/*';input.onchange=async(e)=>{const file=e.target.files[0];if(!file)return;const originalText=usr.value;setText(statusEl,'正在识别图片内容...');closeModal();modalMaskEl=createEl('div',{class:'aig-x7k2-modal-mask'});modalEl=createEl('div',{class:'aig-x7k2-modal'});const title=createEl('div',{class:'aig-x7k2-title'},[createEl('strong',null,['正在识别中'])]);const body=createEl('div',{class:'aig-x7k2-hint'},['Ai正在识别答案中，请稍候..................\n答案识别完成后会自动填充到对应窗口，你可以根据需要进行修改。']);modalEl.appendChild(title);modalEl.appendChild(body);document.documentElement.appendChild(modalMaskEl);document.documentElement.appendChild(modalEl);try{const recognized=await recognizeImageFromFile(file);const newText=originalText?originalText+'\n\n【AI 识别的参考答案】\n'+recognized:'【AI 识别的参考答案】\n'+recognized;usr.value=newText;state.config.global.prompt.user=newText;await saveConfig();log('info','AI 识别完成，已填入提示词框');closeModal();openAlertModal('识别完成','图片内容已识别并添加到“题目/参考答案/评分标准”框中。');}catch(err){log('error','识别失败',{error:String(err?.message||err)});closeModal();openAlertModal('识别失败',friendlyErrorMessage(String(err?.message||err)));}finally{setText(statusEl,'未运行');}};input.click();};const recognizeBtn=createEl('button',{class:'aig-x7k2-btn secondary'},['AI识别答案']);recognizeBtn.onclick=onRecognizeClick;const resetBtn=createEl('button',{class:'aig-x7k2-btn secondary',onclick:async()=>{state.config.global.prompt.user='\n - 对于论述题按标准答案给分，只写结果或过程混乱不给分.\n - 对于填空题，少填但正确的给一半分；多填按错误处理，不给分。';usr.value=state.config.global.prompt.user;await saveConfig();log('info','已恢复默认提示词');}},['恢复默认']);const actionRow=createEl('div',{class:'aig-x7k2-row'},[createEl('label',null,['答案制作']),createEl('div',{style:{display:'flex',gap:'8px',flex:'1'}},[recognizeBtn,resetBtn])]);sec.appendChild(createEl('div',{class:'aig-x7k2-row',style:{alignItems:'stretch',flexDirection:'column'}},[createEl('label',null,['系统提示词']),createEl('div',{style:{display:'flex',marginLeft:'1ch'}},[sys])]));sec.appendChild(createEl('div',{class:'aig-x7k2-row',style:{alignItems:'stretch',flexDirection:'column'}},[createEl('label',null,['题目/参考答案/评分标准']),createEl('div',{style:{display:'flex',marginLeft:'1ch'}},[usr])]));sec.appendChild(actionRow);sec.appendChild(createEl('div',{class:'aig-x7k2-hint'},['系统提示词：写输出约束/安全规则。题目/参考答案/评分标准：每题更新，会并入系统提示词一起发送。建议：让模型只输出 JSON，避免混入解释文字导致解析失败。']));return sec;}
function formatDetailedLogData(data){if(!data||typeof data!=='object')return'';const parts=[];if('score'in data&&data.score!==null&&data.score!==undefined){parts.push(`分数: ${data.score}`);}if('confidence'in data&&data.confidence!==null&&data.confidence!==undefined){parts.push(`置信度: ${(data.confidence*100).toFixed(0)}%`);}if('reason'in data&&data.reason){parts.push(`扣分原因: ${data.reason}`);}if('answer'in data&&data.answer){parts.push(`学生解答: ${data.answer}`);}if('standard'in data&&data.standard){parts.push(`评分标准: ${data.standard}`);}if('difference'in data&&data.difference){parts.push(`差异分析: ${data.difference}`);}if('totalProcessed'in data){parts.push(`已处理: ${data.totalProcessed}`);}if('scoreCount'in data){parts.push(`计划处理: ${data.scoreCount}`);}if('site'in data){parts.push(`站点: ${data.site}`);}if('error'in data&&data.error){parts.push(`错误: ${data.error}`);}return parts.length?('\n  '+parts.join('\n  ')):'';}
function renderLogs(){if(!logsEl)return;const lines=state.logs.slice(-120).map(l=>{const level=String(l.level||'info').toLowerCase();let tag='';if(level==='warn')tag='警告 ';else if(level==='error')tag='错误 ';else if(level&&level!=='info')tag=`${String(level).toUpperCase()} `;let extra='';if(level==='error'&&l.data&&l.data.error)extra=' '+String(l.data.error);if(!state.simplifiedLogs&&l.data){extra=formatDetailedLogData(l.data);}return`[${toHms(l.time||l.timeIso)}] ${tag}${l.message}${extra}`;}).join('\n');setText(logsEl,lines);logsEl.scrollTop=logsEl.scrollHeight;}
function inferImageKind(el){if(!el||!el.tagName)return'element';const tag=el.tagName.toLowerCase();if(tag==='img')return'img';if(tag==='image'&&String(el.namespaceURI||'').includes('svg'))return'svgimage';if(tag==='canvas')return'canvas';try{const bg=getComputedStyle(el).backgroundImage||'';if(bg.includes('url('))return'background';}catch{}return'element';}
function isRenderableEl(el){if(!el)return false;const st=getComputedStyle(el);if(st.display==='none'||st.visibility==='hidden'||Number(st.opacity)===0)return false;return true;}
function getElementArea(el){if(!el)return 0;try{const rect=el.getBoundingClientRect();if(rect&&rect.width>0&&rect.height>0)return rect.width*rect.height;}catch{}try{if(el.tagName&&el.tagName.toLowerCase()==='image'){const box=el.getBBox();if(box&&box.width>0&&box.height>0)return box.width*box.height;}}catch{}try{const w=Number(el.getAttribute('width'));const h=Number(el.getAttribute('height'));if(w>0&&h>0)return w*h;}catch{}return 0;}
function discoverLikelyQuestionImage(){const htmlImgs=Array.from(document.images||[]);const svgImgs=Array.from(document.querySelectorAll('svg image'));const canvases=Array.from(document.querySelectorAll('canvas'));const candidates=[...htmlImgs,...svgImgs,...canvases].filter(el=>isRenderableEl(el)).map(el=>({el,area:getElementArea(el)})).filter(c=>c.area>0&&c.area<window.innerWidth*window.innerHeight*0.9).sort((a,b)=>b.area-a.area);if(candidates.length>0)return candidates[0]?.el||null;const fallback=Array.from(document.querySelectorAll('img, canvas')).find(el=>{const src=el.src||'';return src.includes('answer')||src.includes('card')||src.includes('sheet')||src.includes('student')||src.includes('paper');});return fallback||null;}
function isVisibleEl(el){if(!el)return false;try{const r=el.getBoundingClientRect();if(!r)return false;if(r.width<1||r.height<1)return false;if(r.bottom<0||r.top>window.innerHeight)return false;const st=getComputedStyle(el);if(st.display==='none'||st.visibility==='hidden'||Number(st.opacity)===0)return false;return true;}catch{return false;}}
function discoverScoreContainerHeuristic(){if(siteKey()==='www.tydlk.com'){const keyBox=document.querySelector?.('ul.keyBox');if(keyBox&&isVisibleEl(keyBox))return keyBox;}const stepMark=document.getElementById('stepMark');if(stepMark&&isVisibleEl(stepMark))return stepMark;const clickables=Array.from(document.querySelectorAll('button,[role="button"],input[type="button"],a')).filter(isVisibleEl);const scoreEls=clickables.filter(el=>{const t=(el.getAttribute('data-score')||el.getAttribute('data-value')||el.dataset?.score||el.value||el.innerText||'').trim();return /-?\d+(\.\d+)?/.test(t);});if(scoreEls.length<2)return null;const counts=new Map();for(const el of scoreEls){let cur=el;for(let i=0;i<5&&cur&&cur!==document.body;i++){const key=cur;counts.set(key,(counts.get(key)||0)+1);cur=cur.parentElement;}}let best=null,bestCount=0;for(const[el,c]of counts.entries())if(c>bestCount){best=el;bestCount=c;}return bestCount>=3?best:null;}
function discoverNextButtonHeuristic(){const clickables=Array.from(document.querySelectorAll('button,[role="button"],input[type="button"],a')).filter(isVisibleEl);const patterns=[/下一题/i,/下题/i,/\bnext\b/i];for(const el of clickables){const t=(el.innerText||el.getAttribute('aria-label')||el.getAttribute('title')||'').trim();if(!t)continue;if(patterns.some(p=>p.test(t)))return el;}return null;}
